    if (t >= 1.75 && t < 6.35) {
      const otherX = mix(685, -120, span(t, 1.75, 6.35));
      actor(c, 'passer', Math.floor(t * 7) % 4, otherX, 397, 262);
    }
    if (t > 2.25 && t < 2.9) cameraCue(c, x + 17, feet - height * .66, Math.sin(span(t, 2.25, 2.9) * Math.PI));
